do $seed$
begin
  if not exists (select 1 from public.specialties) then
    insert into public.specialties (key, title_ar, title_en, short_ar, short_en, description_ar, description_en, conditions_ar, conditions_en, techniques, duration_ar, duration_en, recovery_ar, recovery_en, icon, tone, image_url, home_section, tag, summary_ar, summary_en, sort_order) values
      ('lasik', 'الليزك وجراحات تصحيح الإبصار', 'LASIK & Refractive Surgery', 'ودّع النظارة والعدسات اللاصقة', 'Say goodbye to glasses and contacts', 'نوفر طيفاً كاملاً من جراحات تصحيح الإبصار، ونختار التقنية الأنسب لكل مريض بناءً على سمك القرنية وشكلها ودرجة الانكسار ونمط الحياة، لتحقيق أفضل رؤية ممكنة بأعلى درجات الأمان.', 'We offer the full spectrum of vision-correction procedures and select the right technique for each patient based on corneal thickness and shape, prescription and lifestyle — for the best possible vision with the highest safety.', array['قصر النظر', 'طول النظر', 'الاستجماتيزم (اللابؤرية)', 'طول النظر الشيخوخي']::text[], array['Myopia (short-sightedness)', 'Hyperopia (long-sightedness)', 'Astigmatism', 'Presbyopia']::text[], '[{"key":"femto-lasik","name_ar":"الفيمتو ليزك (Femto-LASIK)","name_en":"Femto-LASIK","detail_ar":"صنع شريحة القرنية بالليزر بدلاً من الشفرة لدقة وأمان أعلى.","detail_en":"The corneal flap is created by laser instead of a blade for greater precision and safety.","scene":"femto","image_url":null,"home_section":null,"tag":null},{"key":"smile","name_ar":"الفيمتو سمايل (SMILE)","name_en":"SMILE","detail_ar":"تصحيح عبر فتحة صغيرة دون شريحة، مثالي للرياضيين ومرضى جفاف العين.","detail_en":"Flapless correction through a tiny incision — ideal for athletes and dry-eye patients.","scene":"smile","image_url":null,"home_section":null,"tag":null},{"key":"prk","name_ar":"التصحيح السطحي (PRK / Trans-PRK)","name_en":"Surface ablation (PRK / Trans-PRK)","detail_ar":"بديل آمن للقرنيات الرقيقة دون أي ملامسة للعين.","detail_en":"A safe, no-touch alternative for thinner corneas.","scene":"prk","image_url":null,"home_section":null,"tag":null},{"key":"icl","name_ar":"زراعة العدسات (ICL)","name_en":"Phakic lens implant (ICL)","detail_ar":"للدرجات العالية من قصر النظر أو عند عدم ملاءمة الليزك.","detail_en":"For high prescriptions or when LASIK is not suitable.","scene":"icl","image_url":null,"home_section":null,"tag":null}]'::jsonb, '10 – 15 دقيقة للعينين', '10 – 15 min for both eyes', 'عودة للأنشطة اليومية خلال 24 – 48 ساعة', 'Back to daily activities within 24 – 48 hours', 'crosshair', 'cyan', null, 'surgeries', 'Femto-LASIK · SMILE', 'تصحيح قصر وطول النظر والاستجماتيزم بتقنيات الفيمتو ليزك والسمايل بدقة ميكرونية وتعافٍ سريع.', 'Correct myopia, hyperopia and astigmatism with Femto-LASIK and SMILE — micron-level precision and a fast recovery.', 10),
      ('cataract', 'المياه البيضاء وزراعة العدسات', 'Cataract & Lens Implantation', 'استعد صفاء الرؤية من جديد', 'See the world clearly again', 'إزالة عدسة العين المعتمة بتقنية الفاكو عبر جرح دقيق لا يحتاج إلى غرز، واستبدالها بعدسة صناعية عالية الجودة تُختار بعناية وفق القياسات الحيوية الدقيقة واحتياجات المريض اليومية.', 'The clouded natural lens is removed by phacoemulsification through a stitch-free micro-incision and replaced with a high-quality artificial lens, carefully chosen from precise biometry and your daily visual needs.', array['المياه البيضاء المرتبطة بالتقدم في العمر', 'المياه البيضاء لدى مرضى السكري', 'المياه البيضاء الناتجة عن الإصابات أو الكورتيزون', 'المياه البيضاء الخلقية لدى الأطفال']::text[], array['Age-related cataract', 'Diabetic cataract', 'Traumatic or steroid-induced cataract', 'Congenital cataract in children']::text[], '[{"key":"phaco","name_ar":"الفاكو بالموجات فوق الصوتية","name_en":"Ultrasound phacoemulsification","detail_ar":"تفتيت العدسة المعتمة وإزالتها عبر فتحة لا تتجاوز 2.2 مم.","detail_en":"The cloudy lens is broken up and removed through an opening of just 2.2 mm.","scene":"phaco","image_url":null,"home_section":null,"tag":null},{"key":"multifocal","name_ar":"العدسات متعددة البؤر","name_en":"Multifocal lenses","detail_ar":"رؤية واضحة للبعيد والمتوسط والقريب وتقليل الاعتماد على النظارة.","detail_en":"Clear distance, intermediate and near vision with less reliance on glasses.","scene":"multifocal","image_url":null,"home_section":null,"tag":null},{"key":"toric","name_ar":"عدسات التوريك (Toric)","name_en":"Toric lenses","detail_ar":"تصحيح الاستجماتيزم مع إزالة المياه البيضاء في الإجراء نفسه.","detail_en":"Corrects astigmatism during the same cataract procedure.","scene":"toric","image_url":null,"home_section":null,"tag":null},{"key":"edof","name_ar":"عدسات العمق الممتد (EDOF)","name_en":"Extended depth-of-focus (EDOF)","detail_ar":"مدى رؤية ممتد مع انتقال سلس بين المسافات.","detail_en":"An extended range of vision with smooth transitions between distances.","scene":"edof","image_url":null,"home_section":null,"tag":null}]'::jsonb, '15 – 20 دقيقة', '15 – 20 min', 'تحسن ملحوظ خلال أيام واستقرار تام خلال 4 أسابيع', 'Noticeable improvement within days; fully stable in 4 weeks', 'aperture', 'navy', null, 'surgeries', 'Phaco · Premium IOL', 'إزالة المياه البيضاء بالفاكو عبر جرح دقيق دون غرز، مع زراعة عدسات أحادية أو متعددة البؤر.', 'Stitch-free phaco cataract removal through a micro-incision, with monofocal or multifocal lens implants.', 20),
      ('retina', 'الشبكية والجسم الزجاجي', 'Retina & Vitreous', 'حماية مركز الإبصار', 'Protecting the centre of your vision', 'تشخيص وعلاج أمراض الشبكية بدقة عالية باستخدام التصوير المقطعي وأحدث تقنيات الليزر والحقن والجراحة المجهرية، للحفاظ على البصر ومنع تدهوره.', 'Precise diagnosis and treatment of retinal diseases using OCT imaging and the latest laser, injection and micro-surgical techniques — to preserve sight and prevent deterioration.', array['اعتلال الشبكية السكري', 'الضمور البقعي المرتبط بالعمر', 'انفصال الشبكية', 'ثقب مركز الإبصار والغشاء فوق الشبكي', 'نزيف الجسم الزجاجي']::text[], array['Diabetic retinopathy', 'Age-related macular degeneration', 'Retinal detachment', 'Macular hole & epiretinal membrane', 'Vitreous haemorrhage']::text[], '[{"key":"vitrectomy","name_ar":"استئصال الجسم الزجاجي (Vitrectomy)","name_en":"Pars plana vitrectomy","detail_ar":"جراحة مجهرية دقيقة بمقاس 23/25G لعلاج الانفصال والنزيف.","detail_en":"Precise 23/25G micro-surgery for detachments and haemorrhage.","scene":"vitrectomy","image_url":null,"home_section":null,"tag":null},{"key":"anti-vegf","name_ar":"حقن مضادات VEGF","name_en":"Anti-VEGF injections","detail_ar":"حقن داخل العين لعلاج التورم والأوعية الدموية غير الطبيعية.","detail_en":"Intravitreal injections for oedema and abnormal blood vessels.","scene":"injection","image_url":null,"home_section":"treatments","tag":"Anti-VEGF"},{"key":"retinal-laser","name_ar":"الليزر الضوئي للشبكية","name_en":"Retinal laser photocoagulation","detail_ar":"لعلاج الاعتلال السكري وثقوب الشبكية الطرفية.","detail_en":"For diabetic retinopathy and peripheral retinal tears.","scene":"photocoagulation","image_url":null,"home_section":"treatments","tag":"Laser"},{"key":"oct","name_ar":"التصوير المقطعي (OCT)","name_en":"Optical coherence tomography (OCT)","detail_ar":"تشخيص دقيق ومتابعة طبقات الشبكية بدقة ميكرونية.","detail_en":"Micron-level imaging to diagnose and monitor the retinal layers.","scene":"oct","image_url":null,"home_section":null,"tag":null}]'::jsonb, '30 – 90 دقيقة حسب الحالة', '30 – 90 min depending on the case', 'يختلف حسب الإجراء مع متابعة دورية منتظمة', 'Varies by procedure, with regular scheduled follow-up', 'scanEye', 'deep', null, 'surgeries', 'Vitrectomy', 'علاج انفصال الشبكية وثقب مركز الإبصار ونزيف الجسم الزجاجي بأحدث تقنيات الجراحة المجهرية.', 'Treatment of retinal detachment, macular holes and vitreous haemorrhage with modern micro-surgical techniques.', 30),
      ('glaucoma', 'الجلوكوما (المياه الزرقاء)', 'Glaucoma', 'اكتشاف مبكر يحمي العصب البصري', 'Early detection that protects the optic nerve', 'الجلوكوما مرض صامت قد يُفقد البصر تدريجياً دون أعراض واضحة. نعتمد على التشخيص المبكر الدقيق وخطط علاج مستمرة تهدف إلى ضبط ضغط العين وحماية العصب البصري مدى الحياة.', 'Glaucoma is a silent disease that can gradually steal sight without obvious symptoms. We rely on precise early diagnosis and long-term treatment plans that control eye pressure and protect the optic nerve for life.', array['الجلوكوما مفتوحة الزاوية', 'الجلوكوما ضيقة الزاوية', 'الجلوكوما الثانوية', 'الجلوكوما الخلقية']::text[], array['Open-angle glaucoma', 'Angle-closure glaucoma', 'Secondary glaucoma', 'Congenital glaucoma']::text[], '[{"key":"medical-therapy","name_ar":"العلاج الدوائي الموجّه","name_en":"Targeted medical therapy","detail_ar":"برامج قطرات مخصصة مع متابعة منتظمة لضغط العين.","detail_en":"Personalised eye-drop regimens with regular pressure monitoring.","scene":"drops","image_url":null,"home_section":null,"tag":null},{"key":"slt","name_ar":"الليزر الانتقائي (SLT)","name_en":"Selective laser trabeculoplasty (SLT)","detail_ar":"خفض ضغط العين بالليزر دون جراحة وفي دقائق معدودة.","detail_en":"Lowers eye pressure by laser, without surgery, in minutes.","scene":"slt","image_url":null,"home_section":"treatments","tag":"SLT"},{"key":"yag-iridotomy","name_ar":"ليزر القزحية (YAG)","name_en":"YAG laser iridotomy","detail_ar":"للوقاية والعلاج في حالات الزاوية الضيقة.","detail_en":"Prevention and treatment for narrow-angle cases.","scene":"iridotomy","image_url":null,"home_section":null,"tag":null},{"key":"glaucoma-surgery","name_ar":"الجراحات المتقدمة والصمامات","name_en":"Advanced surgery & drainage devices","detail_ar":"عند عدم كفاية العلاج الدوائي والليزر.","detail_en":"When drops and laser are not enough.","scene":"shunt","image_url":null,"home_section":null,"tag":null}]'::jsonb, '5 – 45 دقيقة حسب الإجراء', '5 – 45 min depending on the procedure', 'متابعة منتظمة مدى الحياة للحفاظ على النتيجة', 'Lifelong regular follow-up to maintain results', 'gauge', 'sky', null, null, null, 'تشخيص مبكر دقيق وعلاج بالقطرات والليزر والجراحة لضبط ضغط العين وحماية العصب البصري.', 'Precise early diagnosis and treatment with drops, laser and surgery to control eye pressure and protect the optic nerve.', 40);
  end if;
end
