do $seed$
begin
  if not exists (select 1 from public.reviews) then
    insert into public.reviews (patient_name_ar, patient_name_en, rating, review_text_ar, review_text_en, procedure_type_ar, procedure_type_en, is_featured_on_home, sort_order) values
      ('أحمد م.', 'Ahmed M.', 5, 'ارتديت النظارة خمسة عشر عاماً، وبعد عملية الفيمتو ليزك أصبحت أرى بوضوح من اليوم التالي. أكثر ما طمأنني هو شرح الدكتور لكل خطوة بصبر واهتمام.', 'I wore glasses for fifteen years. After Femto-LASIK I could see clearly the very next day. What reassured me most was how patiently the doctor explained every step.', 'الفيمتو ليزك', 'Femto-LASIK', true, 10),
      ('سعاد ع.', 'Suad A.', 5, 'أجريت عملية المياه البيضاء للعينين، والحمد لله عادت الألوان زاهية كما كانت، وأصبحت أقرأ دون نظارة. شكراً للدكتور وفريقه على الرعاية والمتابعة.', 'I had cataract surgery on both eyes, and the colours are vivid again just like before — I can even read without glasses. Thank you to the doctor and his team for their care.', 'المياه البيضاء وعدسة متعددة البؤر', 'Cataract & multifocal lens', true, 20),
      ('محمد ك.', 'Mohamed K.', 5, 'والدي مريض سكر منذ سنوات وكان يعاني من تورم في مركز الإبصار. بعد جلسات الحقن والمتابعة المنتظمة تحسّن نظره بشكل ملحوظ. طبيب أمين ومحترم.', 'My father has had diabetes for years and suffered from macular swelling. After the injection sessions and regular follow-up his vision improved noticeably. An honest, respectful doctor.', 'حقن الشبكية', 'Retinal injections', true, 30),
      ('ريم س.', 'Reem S.', 5, 'اكتُشفت عندي قرنية مخروطية وأنا في الجامعة وكنت خائفة جداً. شرح لي الدكتور كل شيء بهدوء، وأجريت عملية التثبيت، والقرنية مستقرة الآن والحمد لله.', 'I was diagnosed with keratoconus at university and was very scared. The doctor calmly explained everything, I had cross-linking, and my cornea is stable now.', 'تثبيت القرنية', 'Corneal cross-linking', true, 40),
      ('خالد ي.', 'Khaled Y.', 5, 'بحكم عملي ونشاطي الرياضي كنت أحتاج حلاً آمناً. رشّح لي الدكتور عملية السمايل بعد فحوصات دقيقة، وكانت التجربة أسرع وأسهل مما توقعت.', 'With my job and sports routine I needed a safe solution. After thorough tests the doctor recommended SMILE — it was faster and easier than I ever expected.', 'الفيمتو سمايل', 'SMILE', true, 50),
      ('نادية ف.', 'Nadia F.', 5, 'عانيت من جفاف وحرقان مزمن بسبب العمل على الكمبيوتر لساعات طويلة. بعد جلسات الـ IPL وبرنامج العلاج تغيّرت حياتي اليومية تماماً.', 'I suffered from chronic dryness and burning from long hours at the computer. After IPL sessions and the treatment programme, my daily life completely changed.', 'علاج جفاف العين', 'Dry eye therapy', true, 60),
      ('حسن ع.', 'Hassan A.', 5, 'اكتشف الدكتور الجلوكوما عندي في فحص روتيني قبل أن أشعر بأي أعراض. أجريت جلسة ليزر SLT وأصبح الضغط منضبطاً. ممتن لدقته وأمانته.', 'The doctor detected glaucoma during a routine check before I had any symptoms. I had an SLT laser session and my pressure is now under control. Grateful for his precision and honesty.', 'علاج الجلوكوما بالليزر', 'Glaucoma laser treatment', true, 70),
      ('منى ر.', 'Mona R.', 5, 'كان مقاس نظري عالياً جداً وقيل لي إن الليزك لا يناسبني. قدّم لي الدكتور حل زراعة العدسة، وجاءت النتيجة أفضل من كل توقعاتي.', 'My prescription was very high and I was told LASIK wasn’t suitable. The doctor offered an ICL implant, and the result exceeded all my expectations.', 'زراعة عدسة ICL', 'ICL lens implant', true, 80),
      ('يوسف ط.', 'Youssef T.', 5, 'تعرضت لانفصال مفاجئ في الشبكية، فأجرى الدكتور العملية بسرعة واحترافية. كانت المتابعة ممتازة واستعدت جزءاً كبيراً من رؤيتي.', 'I had a sudden retinal detachment and the doctor operated quickly and professionally. The follow-up was excellent and I regained a large part of my vision.', 'جراحة الشبكية', 'Retinal surgery', true, 90);
  end if;
end
